def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    ans = [0] * n
    if n == 0 or k == 0:
        return ans

    order = sorted(set(a))
    rank = {v: i + 1 for i, v in enumerate(order)}
    m = len(order)
    bit = [0] * (m + 1)

    def add(i: int, delta: int) -> None:
        while i <= m:
            bit[i] += delta
            i += i & -i

    def prefix(i: int) -> int:
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    for i, value in enumerate(a):
        leave = i - k - 1
        if leave >= 0:
            add(rank[a[leave]], -1)
        r = rank[value]
        ans[i] = prefix(m) - prefix(r)
        add(r, 1)
    return ans
